#!/usr/bin/env bash
# Compile the Noir circuits and (re)generate the Solidity verifiers.
#
# bb emits one self-contained ~100KB file per circuit, and the only part that
# differs between them is the verification key. We split that: the shared
# verifier core lands in src/verifiers/HonkVerifierBase.sol once, and each
# circuit gets a small file holding just its key plus a named contract.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="$PWD"
OUT="$ROOT/src/verifiers"
mkdir -p "$OUT"

split_verifier() {
  local name="$1" src="$2" cap="$3"   # cap = Register | Vote
  # The generated file is: [key section] pragma ^0.8.27 [shared core] contract HonkVerifier
  local core_start key_end contract_start
  core_start=$(grep -n '^pragma solidity \^0.8.27;$' "$src" | head -1 | cut -d: -f1)
  key_end=$((core_start - 1))
  contract_start=$(grep -n '^contract HonkVerifier is' "$src" | head -1 | cut -d: -f1)

  # Shared core, written once (identical for every circuit).
  if [ ! -f "$OUT/HonkVerifierBase.sol" ]; then
    {
      echo "// SPDX-License-Identifier: Apache-2.0"
      echo "// Copyright 2022 Aztec"
      echo "// GENERATED by scripts/build-circuits.sh from \`bb write_solidity_verifier\`."
      echo "// Circuit-independent half of the UltraHonk (ZK) verifier; do not edit."
      sed -n "${core_start},$((contract_start - 1))p" "$src"
    } > "$OUT/HonkVerifierBase.sol"
  fi

  {
    echo "// SPDX-License-Identifier: Apache-2.0"
    echo "// Copyright 2022 Aztec"
    echo "// GENERATED by scripts/build-circuits.sh from circuits/${name}. Do not edit."
    echo "pragma solidity ^0.8.27;"
    echo
    echo "import {Honk, BaseZKHonkVerifier} from \"./HonkVerifierBase.sol\";"
    echo
    sed -n "5,${key_end}p" "$src" \
      | sed "s/HonkVerificationKey/${cap}VerificationKey/g"
    sed -n "${contract_start},\$p" "$src" \
      | sed "s/HonkVerificationKey/${cap}VerificationKey/g; s/^contract HonkVerifier is/contract ${cap}Verifier is/"
  } > "$OUT/${cap}Verifier.sol"
}

for c in register vote; do
  echo "==> circuits/$c"
  (cd "circuits/$c" && nargo compile && bb write_vk -b "target/$c.json" -t evm -o target >/dev/null && bb write_solidity_verifier -k target/vk -t evm -o target/verifier.sol >/dev/null)
done

rm -f "$OUT/HonkVerifierBase.sol"
split_verifier register "$ROOT/circuits/register/target/verifier.sol" Register
split_verifier vote     "$ROOT/circuits/vote/target/verifier.sol"     Vote
echo "==> wrote $OUT"
